use odc::*;

fn flash(ms: u32) {
    pin_set(LED);
    delay(ms);
    pin_clear(LED);
    delay(ms);
}

fn main() {
    pin_output(LED);
    loop {
        flash(100);
        flash(100);
        flash(500);
    }
}

use odc::*;

fn main() {
    pin_output(LED);
    let mut step = 0;
    loop {
        match step {
            0 => {
                pin_set(LED);
                delay(100);
                pin_clear(LED);
            }
            1 => {
                pin_set(LED);
                delay(300);
                pin_clear(LED);
            }
            _ => {
                pin_set(LED);
                delay(600);
                pin_clear(LED);
            }
        }
        delay(300);
        step = step + 1;
        if step > 2 {
            step = 0;
        }
    }
}

