use odc::*;

struct Blinker {
    pin: u8,
    wait: u32,
}

fn blink_once(b: Blinker) -> Blinker {
    pin_set(b.pin);
    delay(b.wait);
    pin_clear(b.pin);
    delay(b.wait);
    b
}

fn main() {
    pin_output(LED);
    let mut led = Blinker { pin: LED, wait: 200 };
    loop {
        led = blink_once(led);
    }
}

